+.document-message + .document-source { margin-top: 12px; }
+
+.markdown { max-width: 80ch; line-height: 1.6; overflow-wrap: anywhere; }
+.markdown > :first-child { margin-top: 0; }
+.markdown h1 { font-size: 1.5rem; }
