+.markdown code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.9em; }
+.markdown :not(pre) > code { background: var(--surface-alt); padding: 1px 4px; border-radius: 3px; }
+.markdown blockquote { margin: 0; padding-left: 12px; border-left: 3px solid var(--border); color: var(--text-muted); }
+.markdown .table-wrap { overflow: auto; }
+.markdown table { border-collapse: collapse; }
+.markdown th, .markdown td { border: 1px solid var(--border); padding: 4px 8px; text-align: left; vertical-align: top; }
+.markdown th { background: var(--surface-alt); }
+.markdown img { max-width: 100%; height: auto; }
+.markdown img.image-unavailable { display: inline-block; min-width: 2em; min-height: 1.4em; padding: 2px 6px; border: 1px dashed var(--border); color: var(--text-muted); font-style: italic; font-size: 0.9em; }
+.markdown input[type='checkbox'] { margin-right: 6px; }
+.markdown hr { border: 0; border-top: 1px solid var(--border); }
+.markdown .link-inert { color: var(--text-muted); text-decoration: underline dotted; cursor: not-allowed; }
