    10	/**
    11	 * Rendering policy on top of react-markdown's defaults (raw HTML stays literal text; unsafe URL schemes
    12	 * such as javascript: are already stripped by the default URL transform):
    13	 * - http(s) links open in a new tab with noopener.
    14	 * - Every other link (relative documents, anchors, stripped unsafe URLs) is inert text.
    15	 * - Only https images are loaded, and they contact the remote server. Anything else shows an
    16	 *   accessible unavailable state and is never resolved against the app or an asset route.
    17	 */
    18	/** react-markdown passes the hast node alongside DOM props; it must not reach the DOM. */
    19	function domProps<T extends { node?: unknown }>(props: T): Omit<T, 'node'> {
    20	  const rest: T = { ...props }
    21	  delete rest.node
    22	  return rest
    23	}
