    26	  a(all) {
    27	    const { href, children, ...props } = domProps(all)
    28	    if (href && EXTERNAL_LINK.test(href)) {
    29	      return <a {...props} href={href} target="_blank" rel="noopener noreferrer">{children}</a>
    30	    }
    31	    return <span {...props} className="link-inert" title="This link is not followed in the viewer">{children}</span>
    32	  },
    33	  img(all) {
    34	    const { src, alt, ...props } = domProps(all)
    35	    const label = alt || 'Image'
