    15	/** Fetches one document. The query is built with URLSearchParams so any character in the path survives. */
    16	export async function fetchDocument(ref: FileRef, signal?: AbortSignal): Promise<FileDocument> {
    17	  const query = new URLSearchParams({ source: ref.source, path: ref.path })
    18	  let response: Response
    19	  try {
    20	    response = await fetch(`/api/file?${query.toString()}`, { signal, cache: 'no-store' })
    21	  } catch (error) {
    22	    if (signal?.aborted) throw error
    23	    throw new DocumentError('failed', 'The API could not be reached. Check that it is running.')
    24	  }
    25	  let body: unknown = null
    26	  try { body = await response.json() } catch { /* not JSON */ }
    27	  const record = body && typeof body === 'object' ? (body as Record<string, unknown>) : null
    28	  const serverMessage = typeof record?.error === 'string' ? record.error : null
    29	  if (response.status === 404) throw new DocumentError('missing', serverMessage ?? 'The file was not found.')
    30	  if (response.status === 400) throw new DocumentError('invalid', serverMessage ?? 'The file link is invalid.')
    31	  if (!response.ok) throw new DocumentError('failed', serverMessage ?? `The API responded with status ${response.status}.`)
    32	  if (!record || typeof record.content !== 'string' || typeof record.hash !== 'string' || record.source !== ref.source || record.path !== ref.path) {
    33	    throw new DocumentError('failed', 'The API returned an unexpected response.')
    34	  }
    35	  return { source: ref.source, path: ref.path, content: record.content, hash: record.hash }
